package com.smeal.service; import com.smeal.dto.NutritionDataDTO; import com.smeal.entity.NutritionData; import com.smeal.exception.ResourceNotFoundException; import com.smeal.repository.NutritionRepository; import java.util.*; import org.springframework.stereotype.Service;
@Service public class NutritionService {private final NutritionRepository repo; public NutritionService(NutritionRepository r){repo=r;} public List<NutritionDataDTO> search(String q,int limit){return repo.findByFoodNameContainingIgnoreCase(q==null?"":q).stream().limit(Math.max(1,Math.min(limit,100))).map(this::dto).toList();} public NutritionDataDTO get(String n){return repo.findByFoodNameIgnoreCase(n).map(this::dto).orElseThrow(()->new ResourceNotFoundException("Food not found"));} private NutritionDataDTO dto(NutritionData n){return new NutritionDataDTO(n.getFoodName(),n.getCaloriesPer100g(),n.getProteins(),n.getCarbs(),n.getFats(),n.getFiber(),n.getSodium(),n.getSugarTotal());}}
